const glossary={API:['Application programming interface','An agreed way for programs to request data or actions from each other.','“Our app uses an API to fetch the snack menu.”'],Scalable:['Able to handle more work','A system can serve more users or data without becoming unusably slow.','“We should test how the app behaves with more people.”'],Agentic:['Able to take steps toward a goal','Software chooses and runs actions, usually with tools and clear limits.','“The assistant can look up a snack and place a draft order.”'],Cloud:['Computing hosted elsewhere','Servers run by another organization that you access over a network.','“We host the website on Render.”'],Cache:['A stored copy for faster access','Keep frequently used data nearby so you do not fetch or compute it every time.','“Cache the menu, but refresh it when prices change.”'],MVP:['Minimum viable product','The smallest usable version that lets you test a specific idea with real users.','“Our MVP is one complete mission people can finish.”']};
