function tool(id){if(id==='rooms'){startRooms();return}if(id==='hotseat'){startHotseat();return}page=id;let content='';if(id==='persona'){content=`<div class="eyebrow">ALTER EGO STUDIO</div><h1>Who are we today?</h1><p class="lesson-body">Pick the job title you are least qualified for. We’ll work on that.</p><div class="form-card">${Object.entries(personas).map(([key,p])=>`<button class="choice ${state.persona===key?'selected':''}" data-persona="${key}"><span class="key">${key==='founder'?'✦':key==='engineer'?'⌘':'✧'}</span><span><strong>${p.name}</strong><br><span class="subtle">${p.title}</span></span></button>`).join('')}<div class="output-card"><h2>${personas[state.persona].title}</h2><p>${personas[state.persona].line}</p><p class="privacy">Job title subject to absolutely no verification.</p></div><div class="actions"><button class="primary" data-tool="pitch">Give me an opening line →</button></div></div>`}if(id==='pitch'){content=`<div class="eyebrow">PITCH MACHINE</div><h1>Make it sound funded.</h1><p class="lesson-body">Tell us what it does. We’ll help you oversell it.</p><form id="pitch-form" class="form-card"><label for="idea">What does your imaginary startup do?</label><input id="idea" class="field" maxlength="90" placeholder="e.g. recommends snacks" value="${safe(state.lastIdea||'recommends snacks')}" required><label for="energy">Founder energy</label><select id="energy" class="field"><option value="sensible" ${state.pitchEnergy==='sensible'?'selected':''}>Confident, mostly grounded</option><option value="bold" ${state.pitchEnergy==='bold'?'selected':''}>Pitch-deck maximalist</option><option value="chaos" ${state.pitchEnergy==='chaos'?'selected':''}>One espresso too many</option></select><div class="actions"><button class="primary" type="submit">Make my pitch ✦</button></div></form><div id="pitch-result">${pitch?pitchOutput():''}</div>`}if(id==='decoder'){const d=glossary[buzzword];content=`<div class="eyebrow">BUZZWORD DECODER</div><h1>What does that word even mean?</h1><p class="lesson-body">Pick a word you’ve heard someone say in a meeting.</p><div class="chip-row">${Object.keys(glossary).map(w=>`<button class="chip ${w===buzzword?'active':''}" data-word-topic="${w}">${w}</button>`).join('')}</div><section class="output-card"><div class="eyebrow">${buzzword}</div><h2>${d[0]}</h2><p>${d[1]}</p><blockquote>${d[2]}</blockquote><button class="quiet-link" data-action="copy-definition">Copy the plain-English version ↗</button></section><div class="actions"><button class="secondary" data-page="path">Put it into practice →</button></div>`}if(id==='meeting'){const m=meeting[meetingStep];content=`<div class="eyebrow">STAND-UP SURVIVAL · ${meetingStep+1} / 3</div><h1>You’re on mute. Unmute.</h1><div class="lesson-prompt" style="margin-top:25px"><img src="/larpy.svg" alt="Larpy"><div class="bubble">${m.q}</div></div><p class="lesson-body">Pick the reply you’d actually want a teammate to give.</p>${m.choices.map((c,i)=>`<button class="choice" data-meeting="${i}" ${meetingAnswered?'disabled':''}><span class="key">${i+1}</span>${c}</button>`).join('')}<div id="meeting-feedback"></div>`}if(id==='mail'){content=`<div class="eyebrow">LARPY’S POST OFFICE</div><h1>Your flex, delivered.</h1><p class="lesson-body">One email with your completed roles, the skills you practised, and your very unofficial title.</p><form id="mail-form" class="form-card"><label for="email">Your email address</label><input id="email" type="email" class="field" autocomplete="email" placeholder="you@example.com" required><label style="display:flex;gap:10px;align-items:start;font-weight:400;line-height:1.6"><input type="checkbox" id="mail-consent" required>Send me one skills receipt through Agentboxd. This does not subscribe me to a mailing list.</label><button class="primary" type="submit" ${canMail()?'':'disabled'}>${canMail()?'Email my receipt':'Finish a role first'}</button><p id="mail-status" role="status" class="lesson-body"></p><p class="privacy">Your email is shared with Agentboxd to deliver this message. Requests are limited to one receipt per day. ${mailReady?'':'The email service is still being connected.'}</p></form>`}shell(`<button class="quiet-link" data-page="lounge">← Back to the lounge</button><div style="margin-top:25px">${content}</div>`)}
function pitchOutput(){return `<section class="output-card"><div class="eyebrow">YOUR OPENING LINE</div><blockquote>${safe(pitch)}</blockquote><p><strong>The normal-person version:</strong> build something useful, test it with someone, and explain what it actually does.</p><div class="actions"><button class="secondary" data-action="copy-pitch">Copy my pitch</button><button class="quiet-link" data-tool="decoder">Decode the jargon →</button></div></section>`}
