function photoWall(){return `<section class="photo-wall" aria-labelledby="photo-title"><div class="photo-intro"><div class="eyebrow">CAUGHT IN THE ACT</div><h2 id="photo-title">Don’t be like these people.<br>Learn to larp.</h2><p>The campus photo is easy.<br>The follow-up question is where it gets awkward.</p></div><div class="photo-strip">${[['Pointing at the future.','Person pointing at a university engineering display'],['CS department. For the photo.','Person posing by a computer science sign'],['Waiting for the code to compile.','Person posing in front of a green computer science wall'],['Head of looking technical.','Person standing by a university engineering display']].map(([caption,alt],i)=>`<figure><img src="/photos/larp-${i+1}.webp" alt="${alt}" width="590" height="787" loading="lazy"><figcaption>${caption}</figcaption></figure>`).join('')}</div><button class="quiet-link" data-page="path">Get a role. Back up the pose. →</button></section>`}
let hotData=null,hotResponse='',hotFeedback='',hotPassed=false,hotBusy=false,hotMethod='GET',hotPath='/demo-inventory',hotRun=0,hotDraft={status:'',total:'',empty:''};
function startHotseat(){hotRun++;page='hotseat';hotData=null;hotResponse='';hotFeedback='';hotPassed=false;hotBusy=false;hotDraft={status:'',total:'',empty:''};hotMethod='GET';hotPath='/demo-inventory';breadcrumb('hotseat-start');hotseat();window.scrollTo(0,0)}
function hotseat(){shell(`<button class="quiet-link" data-page="lounge">← Back to the lounge</button><div class="eyebrow" style="margin-top:25px">THE HOT SEAT · ABOUT 2 MINUTES</div><h1>The demo changed.<br>You’re still presenting.</h1><div class="lesson-prompt" style="margin-top:24px"><img src="/larpy.svg" alt="Larpy"><div class="bubble"><strong class="speaker">Larpy · definitely not panicking</strong>The snack supplier changed the inventory. Fetch the new menu, then tell the room what’s actually available. No multiple choice this time.</div></div><section class="form-card"><h2>1. Get the inventory</h2><p class="lesson-body">The server documents <code>GET /demo-inventory</code>. Each successful request returns fresh sample stock. Errors are real HTTP responses.</p><div class="request-fields"><label for="hot-method">Method<select id="hot-method" class="endpoint" ${hotPassed?'disabled':''}><option ${hotMethod==='GET'?'selected':''}>GET</option><option ${hotMethod==='POST'?'selected':''}>POST</option></select></label><label for="hot-path">Server path<input id="hot-path" class="field" maxlength="60" value="${safe(hotPath)}" ${hotPassed?'disabled':''}></label></div><div class="actions"><button class="secondary" data-action="hot-request" ${hotBusy||hotPassed?'disabled':''}>${hotBusy?'Requesting…':'Send real request ↗'}</button></div><pre class="terminal" aria-live="polite">${safe(hotResponse||'// Your server response will appear here.')}</pre></section><form id="hot-form" class="form-card"><h2>2. Give the room the facts</h2><p class="lesson-body">Use the latest response above. Count stock units, then count the snacks that have none left.</p><div class="hot-answers"><div><label for="hot-status">HTTP success code</label><input class="field" id="hot-status" inputmode="numeric" maxlength="3" value="${safe(hotDraft.status)}" required ${hotPassed?'disabled':''}></div><div><label for="hot-total">Total snack units in stock</label><input class="field" id="hot-total" type="number" min="0" max="99" value="${safe(hotDraft.total)}" required ${hotPassed?'disabled':''}></div><div><label for="hot-empty">Number of sold-out snacks</label><input class="field" id="hot-empty" type="number" min="0" max="3" value="${safe(hotDraft.empty)}" required ${hotPassed?'disabled':''}></div></div><div class="actions"><button class="primary" type="submit" ${!hotData||hotPassed?'disabled':''}>${hotPassed?'Facts checked ✓':'Present the facts'}</button></div><div class="hot-feedback ${hotPassed?'passed':''}" role="status">${hotFeedback}</div>${hotPassed?`<div class="output-card"><div class="eyebrow">WHAT YOU JUST DID</div><h3>Read data you hadn’t seen before.</h3><p>In code, the total is <code>snacks.reduce((sum, snack) =&gt; sum + snack.stock, 0)</code>. Sold-out items match <code>stock === 0</code>.</p><p>You practised this without answer choices. This is still a small exercise, not a job qualification.</p><button type="button" class="secondary" data-action="hot-new">Try a fresh inventory →</button></div>`:''}</form>`)}
async function hotRequest(){if(hotBusy||hotPassed)return;const run=hotRun;hotMethod=document.querySelector('#hot-method').value;hotPath=document.querySelector('#hot-path').value.trim();for(const k of ['status','total','empty'])hotDraft[k]=document.querySelector('#hot-'+k).value;if(!/^\/demo-[a-z-]+$/.test(hotPath)){hotFeedback='Use a /demo- path. This lab only calls our sample server.';hotseat();return}hotBusy=true;hotData=null;hotFeedback='';hotseat();try{const r=await fetch(API+hotPath,{method:hotMethod,headers:{apikey:PUBLIC_KEY},signal:AbortSignal.timeout(10000)});const data=await r.json();if(run!==hotRun)return;hotResponse=`HTTP ${r.status} ${r.statusText}\n${JSON.stringify(data,null,2)}`;if(r.ok&&data.exercise==='inventory')hotData=data;else hotFeedback=r.status===405?'The path exists, but POST is not supported. Use GET to read the menu.':r.status===404?'The path was not found. Check /demo-inventory.':'That is not the inventory response. Use GET /demo-inventory.';breadcrumb('hotseat-response',{status:r.status})}catch(e){if(run!==hotRun)return;hotResponse='The request could not reach the server.';hotFeedback='Check your connection and try again. Your role progress is safe.';capture(e,'hotseat-request')}finally{if(run===hotRun){hotBusy=false;if(page==='hotseat')hotseat()}}}
function checkHotseat(){if(!hotData||hotPassed)return;for(const k of ['status','total','empty'])hotDraft[k]=document.querySelector('#hot-'+k).value;const result=gradeInventory(hotData,hotDraft);hotPassed=result.ok;hotFeedback=result.message;breadcrumb('hotseat-result',{passed:result.ok});if(result.ok){state.hotseatWins=Math.min(999,(Number(state.hotseatWins)||0)+1);touch()}hotseat()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action==='hot-request')hotRequest();if(b.dataset.action==='hot-new')startHotseat()});
document.addEventListener('submit',e=>{if(e.target.id==='hot-form'){e.preventDefault();checkHotseat()}});
let qrFactory=null,qrPromise;
function loadQr(){return qrPromise??=import('./vendor/qrcode-2.0.4.mjs').then(m=>{qrFactory=m.qrcode}).catch(e=>capture(e,'qr-load'))}
let roomGeneration=0;
let roomData=null,roomCode='',roomBusy=false,roomMessage='',roomDraft={status:'',total:'',empty:''};
function startRooms(code=''){roomGeneration++;if(!code&&!roomData)code=storageRead('larp-last-room')||'';page='rooms';if(code){roomCode=code;roomData=null;roomMessage='Opening the room…';roomsView();loadRoom(code)}else roomsView();window.scrollTo(0,0)}
function roomQr(code){if(!qrFactory)return '<span class="subtle">Use the invite link below</span>';const qr=qrFactory(0,'M');qr.addData(location.origin+'/?room='+code);qr.make();return qr.createSvgTag({cellSize:4,margin:16,alt:'Scan to join this Larp Club room',title:'Join the room'});}
function roomsView(){const mine=roomData?.you,locked=mine?.correct||mine?.attempts>=3;shell(`<button class="quiet-link" data-page="lounge">← Back to the lounge</button><div class="eyebrow" style="margin-top:25px">THE GROUP CHAT HAS ENTERED THE MEETING</div><h1>Who actually knows<br>what they’re talking about?</h1><p class="lesson-body">Everyone gets the same snack inventory. Read the response and present three facts. Your answers are checked on the server.</p>${!roomData?`<div class="form-card"><h2>Get everyone in the room.</h2><p class="lesson-body">No sign-up. We give you a nickname. Share the code with people you want to play with.</p><button class="primary" data-action="room-create" ${roomBusy?'disabled':''}>${roomBusy?'One moment…':'Create a room'}</button><form id="room-join" class="room-join"><label for="room-code">Or join with a room code</label><div class="request-fields"><input id="room-code" class="field" maxlength="8" pattern="[A-Fa-f0-9]{8}" placeholder="8-character code" value="${safe(roomCode)}" required><button class="secondary" ${roomBusy?'disabled':''}>Join room →</button></div></form></div>`:`<section class="room-banner"><div class="room-share"><div><span class="eyebrow">ROOM CODE</span><strong>${safe(roomData.code)}</strong><span class="subtle">Open until ${new Date(roomData.expiresAt).toLocaleTimeString('en-CA',{hour:'numeric',minute:'2-digit'})}</span></div><div class="room-qr">${roomQr(roomData.code)}<small>Scan to join</small></div></div><div class="actions"><button class="secondary" data-action="room-copy">Copy invite link</button><button class="secondary" data-action="room-switch">Switch room</button><button class="secondary" data-action="room-refresh" ${roomBusy?'disabled':''}>Refresh results</button></div></section><section class="form-card"><div class="eyebrow">LARPY · YOU’RE PRESENTING NEXT</div><h2>The snack order just landed.</h2><p class="lesson-body">This is a real response from the room API. Everyone sees this same sample data. Tell us the success code, total stock units, and how many snacks are sold out.</p><pre class="terminal">${safe('HTTP 200\n'+JSON.stringify(roomData.inventory,null,2))}</pre><form id="room-answer"><div class="hot-answers"><div><label for="room-status">HTTP success code</label><input id="room-status" class="field" inputmode="numeric" maxlength="3" value="${safe(roomDraft.status)}" required ${locked||roomBusy?'disabled':''}></div><div><label for="room-total">Total units in stock</label><input id="room-total" class="field" type="number" min="0" max="999" value="${safe(roomDraft.total)}" required ${locked||roomBusy?'disabled':''}></div><div><label for="room-empty">Sold-out snacks</label><input id="room-empty" class="field" type="number" min="0" max="3" value="${safe(roomDraft.empty)}" required ${locked||roomBusy?'disabled':''}></div></div><div class="actions"><button class="primary" ${locked||roomBusy?'disabled':''}>${mine?.correct?'You backed it up ✓':locked?'Three attempts used':'Present my answers'}</button><span class="subtle">${mine?.attempts||0} / 3 attempts · 100, 75, then 50 points</span></div></form>${locked?`<div class="output-card"><h3>${mine.correct?'The group chat owes you an apology.':'Time to break character.'}</h3><p>Add each <code>stock</code> value for total units; count <code>stock === 0</code> for sold-out snacks. Try the solo Hot Seat for a fresh practice round.</p><button class="quiet-link" data-tool="hotseat">Practise solo →</button></div>`:''}</section><section class="form-card"><h2>The meeting minutes</h2><p class="privacy">Top 20 submitted players. Nicknames are generated; your score is labelled “you.” Refresh to see new submissions.</p><div class="room-board">${roomData.board.length?roomData.board.map((r,i)=>`<div class="board-row ${mine?.alias===r.alias?'is-you':''}"><span>${i+1}</span><strong>${safe(r.alias)}${mine?.alias===r.alias?' · you':''}</strong><span>${r.correct?r.score+' pts':r.attempts>=3?'Practice time':'Still trying'}</span></div>`).join(''):'<p class="subtle">No submissions yet. An unusually quiet meeting.</p>'}</div><button class="quiet-link" data-action="room-refresh" ${roomBusy?'disabled':''}>Refresh results ↻</button></section>`}<p id="room-message" class="room-message" role="status">${safe(roomMessage)}</p><p class="privacy">Anyone with the invite can view this room’s inventory and nicknames/scores. No email or real name is required. Rooms stop accepting answers after six hours. Scores are for a practice game.</p>`)}
async function roomCall(action,body){await connection;if(!token)throw new Error('Could not connect. Refresh the page and try again.');return api(action,body===undefined?'GET':'POST',body)}
function rememberRoomDraft(){for(const k of ['status','total','empty']){const el=document.querySelector('#room-'+k);if(el)roomDraft[k]=el.value;}}
async function loadRoom(code,run=roomGeneration){roomBusy=true;if(page==='rooms')roomsView();try{const [data]=await Promise.all([roomCall('room?code='+encodeURIComponent(code)),loadQr()]);if(run!==roomGeneration)return;roomData=data;roomCode=data.code;storageWrite('larp-last-room',data.code);if(page==='rooms')window.history?.replaceState(null,'','/?room='+data.code);if(roomMessage==='Opening the room…')roomMessage='';breadcrumb('room-open')}catch(e){if(run!==roomGeneration)return;roomMessage=e.message;if(!e.status||e.status>=500)capture(new Error('Room could not load'),'group-room')}finally{if(run===roomGeneration){roomBusy=false;if(page==='rooms')roomsView()}}}
async function createRoom(){if(roomBusy)return;const run=roomGeneration;roomBusy=true;roomMessage='Making a room…';roomsView();try{const data=await roomCall('rooms',{});if(run!==roomGeneration)return;roomDraft={status:'',total:'',empty:''};roomMessage='Share the invite, then see who can back it up.';await loadRoom(data.code,run);breadcrumb('room-created')}catch(e){if(run!==roomGeneration)return;roomMessage=e.message;if(!e.status||e.status>=500)capture(new Error('Room creation failed'),'group-room')}finally{if(run===roomGeneration){roomBusy=false;if(page==='rooms')roomsView()}}}
async function submitRoom(){if(roomBusy||!roomData)return;const run=roomGeneration,code=roomData.code;rememberRoomDraft();roomBusy=true;roomMessage='Checking with the server…';roomsView();try{const result=await roomCall('room-submit',{code,...Object.fromEntries(Object.entries(roomDraft).map(([k,v])=>[k,Number(v)]))});if(run!==roomGeneration)return;roomMessage=result.correct?'Correct. You brought evidence to the meeting.':result.locked?'That was your third attempt. Check the explanation and try a solo practice round.':'Not quite. Check the HTTP code, add the stock values, and count the zeroes. You can try again.';breadcrumb('room-submitted',{correct:result.correct,attempts:result.attempts});await loadRoom(code,run)}catch(e){if(run!==roomGeneration)return;roomMessage=e.message;if(!e.status||e.status>=500)capture(new Error('Room answer submission failed'),'group-room')}finally{if(run===roomGeneration){roomBusy=false;if(page==='rooms')roomsView()}}}
document.addEventListener('submit',e=>{if(e.target.id==='room-join'){e.preventDefault();roomDraft={status:'',total:'',empty:''};startRooms(document.querySelector('#room-code').value.trim().toUpperCase())}if(e.target.id==='room-answer'){e.preventDefault();submitRoom()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='room-switch'){window.history?.replaceState(null,'','/');roomGeneration++;roomBusy=false;roomData=null;roomCode='';roomMessage='';roomDraft={status:'',total:'',empty:''};storageWrite('larp-last-room','');roomsView()}if(a==='room-create')createRoom();if(a==='room-refresh'&&roomData&&!roomBusy){rememberRoomDraft();loadRoom(roomData.code);}if(a==='room-copy'&&roomData)copy(location.origin+'/?room='+roomData.code)});
const wordChoices=['a server.','My app','JSON','from','requests'];
function lesson(){page='lesson';const l=lessons[state.step];if(!l)return complete();const final=state.step===5;app.innerHTML=`<div class="lesson-screen"><header class="lesson-top"><button class="close-btn" data-page="path" aria-label="Leave lesson">×</button><div class="bar" role="progressbar" aria-valuenow="${state.step}" aria-valuemin="0" aria-valuemax="6" aria-label="Mission progress"><div style="width:${state.step/6*100}%"></div></div><span class="lesson-counter">${state.step+1} / 6</span><span style="font-weight:800;color:#b0852d">✦ ${xp()}</span></header><main class="lesson-content"><div class="eyebrow">THE API INCIDENT · ${titles[state.step]}</div><h1>${final?'Build the plain-English explanation.':l.title}</h1><div class="lesson-prompt"><img src="/larpy.svg" alt="Larpy"><div class="bubble">${final?'No jargon this time. Put the tiles in order to explain what your app does.':l.quote}</div></div><p class="lesson-body">${final?'Choose the tiles to make a sentence. Tap a tile in your answer to put it back.':l.body}</p>${l.code?`<pre class="terminal">${safe(l.code)}</pre>`:''}${final?`<div class="answer-bank">${words.length?words.map((n,i)=>`<button class="word" data-remove-word="${i}" ${passed?'disabled':''}>${wordChoices[n]}</button>`).join(''):'<span class="empty-words">Your explanation goes here…</span>'}</div><div class="word-bank">${wordChoices.map((w,i)=>`<button class="word" data-word="${i}" ${words.includes(i)||passed?'disabled':''}>${w}</button>`).join('')}</div>`:l.endpoint?`<label for="endpoint" class="subtle">Request endpoint</label><select class="endpoint" id="endpoint" ${passed?'disabled':''}><option value="">Choose a request…</option><option value="wrong">GET /api/unicorns</option><option value="correct" ${passed?'selected':''}>GET /api/snacks</option><option value="post">POST /api/snacks</option></select><div class="terminal" id="response">${passed?'HTTP/1.1 200 OK\n{ "snacks": [{ "name": "Debugging Doritos", "stock": 3 }] }':'// Ready when you are.'}</div><button class="secondary" data-action="request" ${passed?'disabled':''}>Send request ↗</button>`:l.choices.map((c,i)=>`<button class="choice ${selected===i?'selected':''} ${passed&&selected===i?'correct':''}" data-choice="${i}" ${passed?'disabled':''}><span class="key">${i+1}</span>${safe(c)}</button>`).join('')}<button class="hint" data-action="hint">A little help, Larpy?</button><div class="story-save">Keyboard: 1–9 pick an answer, Enter checks or continues.</div></main><footer class="lesson-bottom"><div class="lesson-feedback ${passed?'good':feedback?'bad':''}" role="status">${feedback||(passed?'Nicely done.': 'Take your time. There’s no penalty for being curious.')}</div><button class="primary" data-action="${passed?'next':'check'}" ${!passed&&(final?words.length!==5:l.endpoint||selected===null)?'disabled':''}>${passed?(state.step===5?'Finish →':'Continue →'):'Check'}</button></footer></div>`}
function reset(){selected=null;feedback='';passed=false;words=[]}
function start(i){state.step=i;reset();lesson();window.scrollTo(0,0)}
function check(){if(state.step!==5&&selected===null)return;const l=lessons[state.step],correct=state.step===5?words.join(',')==='1,4,2,3,0':l.correct===undefined||selected===l.correct;if(correct){passed=true;feedback=state.step===5?'Exactly. Your app requests JSON from a server. You can explain the whole flow now.':l.explain;state.answers[state.step]=state.step===5?'My app requests JSON from a server.':selected;touch()}else{state.mistakes++;feedback=state.step===5?'Try: who is asking, what do they request, and where does it come from?':'Not quite. Look for the answer that describes what the program actually does.';save()}lesson();announce(feedback)}
function request(){const value=document.querySelector('#endpoint').value;if(!value)return;if(value==='correct'){passed=true;feedback=lessons[2].explain;state.answers[2]='GET /api/snacks';touch();lesson()}else{state.mistakes++;save();document.querySelector('#response').textContent=value==='post'?'HTTP/1.1 405 Method Not Allowed\nUse GET to read the snack menu.':'HTTP/1.1 404 Not Found\nNo unicorns here. Check the documented endpoint.';document.querySelector('.lesson-feedback').textContent='Read the response, adjust the request, and try again.';announce('Request failed. Read the response and try again.')}}
function complete(){page='complete';state.completed=true;save();app.innerHTML=`<main class="success-screen"><img src="/larpy.svg" alt="Larpy celebrating"><div class="eyebrow">THE FLEX HAS BEEN EARNED</div><h1>You know what you’re talking about.</h1><p>Junior Vice President of Knowing What HTTP Is.<br>It’s a long title. You’ve earned every syllable.</p><div class="stat-grid"><div class="metric"><strong>${xp()}</strong><span>Total XP</span></div><div class="metric"><strong>6</strong><span>Steps complete</span></div><div class="metric"><strong>${state.hints}</strong><span>Hints explored</span></div></div><div class="skill-list"><strong>Your actual skills receipt</strong><br>✓ Explain APIs in plain English<br>✓ Choose a GET endpoint and interpret 200 OK<br>✓ Read a value from JSON<br>✓ Handle a 503 failure responsibly</div><p class="privacy">A practice badge, not a professional certification.</p><div class="actions" style="justify-content:center"><button class="primary" data-tool="mail">Email my receipt</button><button class="secondary" data-page="lounge">Back to the lounge</button></div></main>`}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Go make an entrance.')}catch{toast('You can select and copy the text above.')}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if(d.page){window.history?.replaceState(null,'','/');page=d.page;render();window.scrollTo(0,0);return}if(d.tool){if(d.tool!=='rooms')window.history?.replaceState(null,'','/');if(d.tool==='meeting'){meetingStep=0;meetingAnswered=false}tool(d.tool);window.scrollTo(0,0);return}if(d.node!==undefined){start(Number(d.node));return}if(d.persona){state.persona=d.persona;save();tool('persona');return}if(d.wordTopic){buzzword=d.wordTopic;tool('decoder');return}if(d.choice!==undefined){selected=Number(d.choice);feedback='';lesson();return}if(d.word!==undefined){words.push(Number(d.word));lesson();return}if(d.removeWord!==undefined){words.splice(Number(d.removeWord),1);lesson();return}if(d.meeting!==undefined){meetingAnswered=true;const good=Number(d.meeting)===meeting[meetingStep].best;if(good){const seen=state.meetingCorrect||[];if(!seen.includes(meetingStep))seen.push(meetingStep);state.meetingCorrect=seen;state.meetingScore=seen.length;touch()}document.querySelectorAll('[data-meeting]').forEach(b=>b.disabled=true);document.querySelector('#meeting-feedback').innerHTML=`<div class="output-card"><h3>${good?'That’s the line.':'Memorable. Maybe not helpful.'}</h3><p>${meeting[meetingStep].reply}</p><button class="primary" data-action="meeting-next">${meetingStep<2?'Next question →':'Back to the lounge'}</button></div>`;return}const a=d.action;if(a==='check')check();if(a==='request')request();if(a==='hint'){state.hints++;feedback=state.step===5?'“My app” starts the sentence. “a server.” ends it.':lessons[state.step].hint;save();lesson()}if(a==='next'){state.step++;reset();save();if(state.step===6)complete();else lesson();window.scrollTo(0,0)}if(a==='meeting-next'){if(meetingStep<2){meetingStep++;meetingAnswered=false;tool('meeting')}else{page='lounge';render()}}if(a==='copy-pitch')copy(pitch);if(a==='copy-definition')copy(glossary[buzzword][1])});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='pitch-form'){const idea=document.querySelector('#idea').value.trim(),energy=document.querySelector('#energy').value;if(!idea)return;pitch=energy==='sensible'?`We’re building a product that ${idea.toLowerCase()}. One clear problem, one useful first version, and real feedback before we scale.`:energy==='bold'?`We’re reimagining how the world ${idea.toLowerCase()} with an API-first platform. Small MVP. Unreasonably large vision.`:`Imagine a world that ${idea.toLowerCase()}. Now make it agentic. Now put it in the cloud. The deck is ready. The product is emotionally available.`;state.lastPitch=pitch;state.lastIdea=idea;state.pitchEnergy=energy;state.pitchCount++;touch();document.querySelector('#pitch-result').innerHTML=pitchOutput();announce('Your pitch is ready.')}if(e.target.id==='mail-form'){const button=e.target.querySelector('button'),status=document.querySelector('#mail-status');button.disabled=true;status.textContent='Sending your request…';try{await pushProgress();await api('receipt','POST',{email:document.querySelector('#email').value.trim(),consent:document.querySelector('#mail-consent').checked});status.textContent='Your receipt is queued. Check your inbox shortly.'}catch(error){status.textContent=error.message;capture(new Error('Receipt delivery failed'),'email-receipt');button.disabled=false}}});
if(new URLSearchParams(location.search).has('diagnostics')){const b=document.createElement('button');b.className='secondary diagnostic';b.textContent='Send Sentry integration test';b.onclick=()=>{capture(new Error('Larp Club monitoring integration test'),'integration-verification');b.textContent='Test event sent ✓';b.disabled=true};document.body.append(b)}
let requestMethod='GET',requestPath='/demo-snacks';
let sceneRun=0;
let campaignId='founder',sceneIndex=0,sceneChoice=null,scenePicks=[],sceneFeedback='',scenePassed=false,requestBusy=false,lastResponse='',responseClass='';
function recordFor(id){state.campaigns??={};return state.campaigns[id]??={next:0,solved:{},attempts:{},done:false}}
function resetScene(){sceneRun++;const s=campaigns[campaignId].scenes[sceneIndex];requestMethod='GET';requestPath=s.target||'/demo-snacks';sceneChoice=null;scenePicks=[];sceneFeedback='';scenePassed=false;lastResponse='';responseClass='';requestBusy=false}
function startCampaign(id,replay=false){if(!campaigns[id])return;breadcrumb('role-start',{role:id,replay});campaignId=id;const r=recordFor(id);sceneIndex=replay?0:Math.min(r.next,campaigns[id].scenes.length-1);resetScene();if(r.done&&!replay){campaignDebrief();return}campaignScene();window.scrollTo(0,0)}
function campaignHub(){shell(`<div class="eyebrow">PICK YOUR NEXT ROLE</div><h1>The plot thickens.</h1><p class="lesson-body">Walk into a situation you’re wildly underqualified for. Leave with a story—and something you can actually do.</p><div class="campaign-list">${Object.entries(campaigns).map(([id,c])=>{const r=recordFor(id),n=Object.keys(r.solved).length;return `<article class="campaign-card"><div class="campaign-card-icon">${c.icon}</div><div><div class="eyebrow">${c.duration} · ${c.scenes.length} SCENES</div><h2>${c.title}</h2><p>${c.premise}</p><div class="bar"><div style="width:${n/c.scenes.length*100}%"></div></div><div class="goal-row"><span>${n} / ${c.scenes.length} scenes earned</span><button class="quiet-link" data-campaign="${id}">${r.done?'View my debrief':n?'Continue the story':'Play this role'} →</button></div></div></article>`}).join('')}</div><button class="quiet-link" data-action="legacy-path">Open the original API practice →</button>`)}
function campaignScene(){page='campaign';const c=campaigns[campaignId],s=c.scenes[sceneIndex];const selectedCount=scenePicks.length;app.innerHTML=`<div class="lesson-screen"><header class="lesson-top"><button class="close-btn" data-page="path" aria-label="Save and leave story">×</button><div class="bar" role="progressbar" aria-label="Story progress" aria-valuemin="0" aria-valuemax="${c.scenes.length}" aria-valuenow="${sceneIndex}"><div style="width:${sceneIndex/c.scenes.length*100}%"></div></div><span class="lesson-counter">${sceneIndex+1} / ${c.scenes.length}</span><span class="story-role">${c.icon} ${c.role}</span></header><main class="lesson-content"><div class="eyebrow">${c.title} · SCENE ${sceneIndex+1}</div><h1>${s.title}</h1><div class="lesson-prompt"><img src="/larpy.svg" alt="Larpy"><div class="bubble"><strong class="speaker">${s.speaker}</strong>${s.line}</div></div>${s.type==='choice'?s.options.map((o,i)=>({o,i})).sort((a,b)=>((a.i+sceneIndex+1)%s.options.length)-((b.i+sceneIndex+1)%s.options.length)).map(({o,i},display)=>`<button class="choice ${sceneChoice===i?'selected':''} ${scenePassed&&sceneChoice===i?'correct':''}" data-scene-choice="${i}" ${scenePassed?'disabled':''}><span class="key">${display+1}</span>${safe(o.text)}</button>`).join(''):s.type==='scope'?`<p class="subtle">${selectedCount} of 2 selected · tap again to remove</p>${s.items.map((t,i)=>`<button class="choice ${scenePicks.includes(i)?'selected':''}" data-scene-pick="${i}" aria-pressed="${scenePicks.includes(i)}" ${scenePassed?'disabled':''}><span class="key">${scenePicks.includes(i)?'✓':'+'}</span>${t}</button>`).join('')}`:`<section class="request-lab"><div class="request-fields"><label for="live-method">Method<select id="live-method" class="endpoint" ${scenePassed?'disabled':''}><option ${requestMethod==='GET'?'selected':''}>GET</option><option ${requestMethod==='POST'?'selected':''}>POST</option></select></label><label for="live-path">Server path<input id="live-path" class="field" value="${safe(requestPath)}" maxlength="60" ${scenePassed?'disabled':''}></label></div><div class="chip-row">${(s.presets||['/demo-snacks','/demo-missing','/demo-outage']).map(p=>`<button class="chip" data-path-preset="${p}" ${scenePassed?'disabled':''}>${{['/demo-snacks']:'Snack menu',['/demo-missing']:'Missing page',['/demo-outage']:'Server outage',['/demo-inventory']:'Inventory'}[p]||p}</button>`).join('')}</div><button class="secondary" data-action="live-request" ${requestBusy||scenePassed?'disabled':''}>${requestBusy?'Requesting…':'Send real request ↗'}</button><pre class="terminal ${responseClass}" id="live-response" aria-live="polite">${safe(lastResponse||'// Real HTTP requests to the Larp Club demo server.\n// No personal data or paid AI calls.')}</pre></section>`}<button class="hint" data-action="scene-hint">Break character · ask Larpy</button><div class="story-save">Your progress saves after each scene. Wrong turns are part of the bit. Keyboard: 1–9 pick a reply, Enter continues.</div></main><footer class="lesson-bottom"><div class="lesson-feedback ${scenePassed?'good':sceneFeedback?'bad':''}" role="status">${sceneFeedback||(s.type==='request'?'Use the request lab above. Inspect the response, then recover to a successful GET.':'Commit to a reply. See what happens.')}</div><button class="primary" data-action="${scenePassed?'scene-next':'scene-check'}" ${!scenePassed&&(s.type==='choice'?sceneChoice===null:s.type==='scope'?selectedCount!==2:true)?'disabled':''}>${scenePassed?(sceneIndex===c.scenes.length-1?'See my debrief →':'Next scene →'):(s.type==='request'?'Complete the request above':'Commit to the bit')}</button></footer></div>`}
function sceneSolve(){const r=recordFor(campaignId);r.solved[sceneIndex]=true;r.next=Math.max(r.next,sceneIndex+1);scenePassed=true;touch()}
function sceneCheck(){const s=campaigns[campaignId].scenes[sceneIndex],r=recordFor(campaignId);r.attempts[sceneIndex]=(r.attempts[sceneIndex]||0)+1;let good;if(s.type==='choice'){const o=s.options[sceneChoice];if(!o)return;good=o.correct;sceneFeedback=`<strong>${safe(o.outcome)}</strong><br>${safe(o.learn)}`}else{good=evaluateSelection(s,scenePicks);sceneFeedback=good?`<strong>A small scope. A suspiciously good decision.</strong><br>${s.learn}`:'The pitch is ambitious, but the user still needs the basics. Pick the two items that make the core task work and let us check whether it succeeds.'}breadcrumb('scene-result',{role:campaignId,scene:sceneIndex,passed:Boolean(good)});if(good)sceneSolve();else save();campaignScene();announce(good?'Scene completed.':'Try another reply. Your progress is safe.')}
async function liveRequest(){if(requestBusy||scenePassed)return;const run=sceneRun;const method=document.querySelector('#live-method').value,path=document.querySelector('#live-path').value.trim();requestMethod=method;requestPath=path;const s=campaigns[campaignId].scenes[sceneIndex],target=s.target||'/demo-snacks';if(!/^\/demo-[a-z-]+$/.test(path)){sceneFeedback=`Use a demo path such as ${target}. This lab only calls our demo server.`;campaignScene();return}requestBusy=true;const r=recordFor(campaignId);r.attempts[sceneIndex]=(r.attempts[sceneIndex]||0)+1;document.querySelector('[data-action="live-request"]').disabled=true;document.querySelector('[data-action="live-request"]').textContent='Requesting…';try{const response=await fetch(API+path,{method,headers:{apikey:PUBLIC_KEY},signal:AbortSignal.timeout(10000)});const data=await response.json();if(run!==sceneRun||page!=='campaign')return;lastResponse=`HTTP ${response.status} ${response.statusText}\n${JSON.stringify(data,null,2)}`;if(response.ok&&path===target&&Array.isArray(data.snacks)){sceneFeedback='<strong>The data is live. You actually called a server.</strong><br>GET read the endpoint; 200 means success. The JSON body is structured data you can summarize and display.';sceneSolve();responseClass='response-success'}else{responseClass='response-error';sceneFeedback=response.ok?`This request succeeded, but this scene needs GET ${target}. Use the documented path.`:response.status===404?`404 means the requested path was not found. Keep GET, change the path to ${target}, and try again.`:response.status===405?`405 means the path exists but that method is not supported. Switch to GET to read the ${target==='/demo-inventory'?'inventory':'menu'}.`:`503 means the server is unavailable. This route deliberately simulates an outage; recover using GET ${target}.`;save()}}catch(e){if(run!==sceneRun||page!=='campaign')return;lastResponse='The request did not reach the server.';sceneFeedback='Connection trouble. Your story is saved. Try the request again when the network is available.';capture(e,'campaign-request')}finally{if(run===sceneRun){requestBusy=false;if(page==='campaign')campaignScene()}}}
function campaignDebrief(){page='debrief';const c=campaigns[campaignId],r=recordFor(campaignId),score=campaignScore(r);const finished=score.solved===c.scenes.length;if(finished){r.done=true;if(campaignId==='founder')state.completed=true;save()}app.innerHTML=`<main class="success-screen"><img src="/larpy.svg" alt="Larpy celebrating"><div class="eyebrow">${finished?'SHIFT COMPLETE':'YOUR STORY SO FAR'}</div><h1>${finished?'You pulled it off.':'There’s more to this character.'}</h1><p>${c.title}<br><strong>${c.role}</strong></p><div class="stat-grid"><div class="metric"><strong>${score.solved}/${c.scenes.length}</strong><span>scenes earned</span></div><div class="metric"><strong>${score.firstTry}</strong><span>first-try decisions</span></div><div class="metric"><strong>${xp()}</strong><span>total XP</span></div></div><div class="skill-list"><strong>Here’s what you actually demonstrated</strong><br>${c.scenes.filter((s,i)=>r.solved[i]).map(s=>'✓ '+s.skill).join('<br>')}</div><p class="privacy">Skills demonstrated in a guided scenario. A playful title, not a professional qualification.</p><div class="actions" style="justify-content:center"><button class="primary" data-page="path">Choose my next role →</button>${finished?`<button class="secondary" data-replay="${campaignId}">Replay the story</button>`:''}${finished?'<button class="secondary" data-tool="mail">Email my receipt</button>':''}</div></main>`}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if(d.campaign){startCampaign(d.campaign);return}if(d.replay){startCampaign(d.replay,true);return}if(d.sceneChoice!==undefined){sceneChoice=Number(d.sceneChoice);sceneFeedback='';campaignScene();return}if(d.scenePick!==undefined){const n=Number(d.scenePick);if(scenePicks.includes(n))scenePicks=scenePicks.filter(i=>i!==n);else if(scenePicks.length<2)scenePicks.push(n);else toast('Pick two. Tap a selected item to swap it.');sceneFeedback='';campaignScene();return}if(d.pathPreset){document.querySelector('#live-path').value=d.pathPreset;return}if(d.action==='scene-check')sceneCheck();if(d.action==='live-request')liveRequest();if(d.action==='scene-next'){sceneIndex++;resetScene();if(sceneIndex===campaigns[campaignId].scenes.length)campaignDebrief();else campaignScene();window.scrollTo(0,0)}if(d.action==='scene-hint'){const s=campaigns[campaignId].scenes[sceneIndex];sceneFeedback=s.type==='request'?`Out of character: GET reads data. Use the documented ${s.target||'/demo-snacks'} path. You can inspect errors with the other presets.`:s.type==='scope'?s.learn:'Out of character: look for a specific action, observable evidence, and a claim you could explain to a teammate.';state.hints++;save();campaignScene()}if(d.action==='legacy-path')legacyPath()});

render();const connection=connect();const invitedRoom=new URLSearchParams(location.search).get('room');if(invitedRoom&&/^[a-f0-9]{8}$/i.test(invitedRoom))startRooms(invitedRoom.toUpperCase());
document.addEventListener('keydown',e=>handleShortcut(e,{page,root:document}));
